#include <algorithm>
#include <utility>
using namespace std;
typedef unsigned int u_int;
struct nglListNode;
typedef void (*nglCustomNodeFn)(u_int *&, void *);
struct nglSortInfo { u_int Type; union { float Dist; u_int Hash; }; };
struct nglListNode { nglListNode* Next; u_int Type; nglSortInfo SortInfo; nglCustomNodeFn NodeFn; void* NodeData; };
struct nglScene {
  nglScene* Parent; nglScene* NextSibling; nglScene* FirstChild; nglScene* LastChild;
  char Data[1008];
  nglListNode* OpaqueRenderList; nglListNode* TransRenderList;
  u_int OpaqueListCount, TransListCount;
  char Tail[140]; float AnimTime; u_int IFLFrame;
};
class nglOpaqueCompare { public: bool operator()(const pair<nglListNode*,u_int>& a,const pair<nglListNode*,u_int>& b) { return a.second < b.second; } };
class nglTransCompare { public: bool operator()(const pair<nglListNode*,u_int>& a,const pair<nglListNode*,u_int>& b) { if ((float&)a.second > (float&)b.second) return true; else if ((float&)a.second < (float&)b.second) return false; else return (u_int)a.first < (u_int)b.first; } };
extern float nglIFLSpeed;
extern nglScene* nglCurScene;
extern nglListNode* nglPrevNode;
extern int nglTestNodeStart, nglTestNodeEnd, nglNodeCount;
inline bool nglEvalTestNode() { nglNodeCount++; if (nglNodeCount < nglTestNodeStart || nglNodeCount > nglTestNodeEnd) return false; return true; }
inline int nglFTOI(float f) { return (int)f; }
void nglCalculateMatrices(nglScene*, int = 0, int = 0);
void nglVif1SetupScene(u_int *&, nglScene*, bool);
void nglOpenRenderList(pair<nglListNode*,u_int>*, nglListNode*, u_int);
void nglCloseRenderList(pair<nglListNode*,u_int>*, nglListNode*&, u_int);
void nglVif1FlushSPAD(u_int *&, bool);
__asm__(".equ nglIFLSpeed,0x004AB808");
__asm__(".equ nglCurScene,0x004BBD04");
__asm__(".equ nglPrevNode,0x004BC050");
__asm__(".equ nglTestNodeStart,0x004BC03C");
__asm__(".equ nglTestNodeEnd,0x004BC040");
__asm__(".equ nglNodeCount,0x004BC044");
__asm__(".equ nglCalculateMatrices__FP8nglSceneii,0x003986D8");
__asm__(".equ nglVif1SetupScene__FRPUiP8nglSceneb,0x0039A128");
__asm__(".equ nglOpenRenderList__FPt4pair2ZP11nglListNodeZUiP11nglListNodeUi,0x0039A0B8");
__asm__(".equ nglCloseRenderList__FPt4pair2ZP11nglListNodeZUiRP11nglListNodeUi,0x0039A0E8");
__asm__(".equ nglVif1FlushSPAD__FRPUib,0x003996B8");
#define NGL_SCRATCHPAD_MEM ((void*)0x70000000)
#define START_PROF_TIMER(x)
#define STOP_PROF_TIMER(x)
void nglVif1RenderScene( u_int*& Packet, nglScene* Scene )
{
  // First recursively render the children to take care of dependencies.
  nglScene* Child = Scene->FirstChild;
  while ( Child )
  {
    nglVif1RenderScene( Packet, Child );
    Child = Child->NextSibling;
  }

  // Calculate the current IFL frame.
  Scene->IFLFrame = nglFTOI( Scene->AnimTime * nglIFLSpeed );

  // Calculate matrices and clip planes in all necessary spaces.
  nglCalculateMatrices(Scene);

  nglVif1SetupScene( Packet, Scene, /*ClearEnable*/ true );

  START_PROF_TIMER( proftimer_send_sort );
  pair<nglListNode*,u_int>* NodeTbl = (pair<nglListNode*,u_int>*)NGL_SCRATCHPAD_MEM + 8;
  nglOpenRenderList( NodeTbl, Scene->OpaqueRenderList, Scene->OpaqueListCount );
  sort( NodeTbl, NodeTbl + Scene->OpaqueListCount, nglOpaqueCompare() );
  nglCloseRenderList( NodeTbl, Scene->OpaqueRenderList, Scene->OpaqueListCount );
  STOP_PROF_TIMER( proftimer_send_sort );

  // Set nglCurScene to currently rendering scene, so that the node callback can use it.
  // Note: nglVif1AddTextureStreaming is used by many node callback functions, and implicitly
  //  references nglCurScene->RenderTarget.
  nglScene *nglCurScene_save = nglCurScene;
  nglCurScene = Scene;

  // Render the nodes in the scene.
  START_PROF_TIMER( proftimer_send_addnodes );

  nglListNode* Node = Scene->OpaqueRenderList;
  while ( Node )
  {
    if ( !nglEvalTestNode() )
    {
      nglPrevNode = Node;
      Node = Node->Next;
      continue;
    }

    // Execute the callback function that adds this node to the DMA chain.
    Node->NodeFn( Packet, Node->NodeData );

    nglPrevNode = Node;
    Node = Node->Next;
  }
  STOP_PROF_TIMER( proftimer_send_addnodes );

  START_PROF_TIMER( proftimer_send_sort );
  nglVif1FlushSPAD( Packet, true );
  nglOpenRenderList( NodeTbl, Scene->TransRenderList, Scene->TransListCount );
  sort( NodeTbl, NodeTbl + Scene->TransListCount, nglTransCompare() );
  nglCloseRenderList( NodeTbl, Scene->TransRenderList, Scene->TransListCount );
  STOP_PROF_TIMER( proftimer_send_sort );

  START_PROF_TIMER( proftimer_send_addnodes );
  Node = (nglListNode*)Scene->TransRenderList;
  while ( Node )
  {
    if ( !nglEvalTestNode() )
    {
      nglPrevNode = Node;
      Node = Node->Next;
      continue;
    }

    // Execute the callback function that adds this node to the DMA chain.
    Node->NodeFn( Packet, Node->NodeData );

    nglPrevNode = Node;
    Node = Node->Next;
  }
  STOP_PROF_TIMER( proftimer_send_addnodes );

  // Restore nglCurScene to its original value
  nglCurScene = nglCurScene_save;
}
